SELECT
/* 新增客户*/
(SELECT
COUNT(1)
FROM
crm_pre_customer
WHERE
create_time > #{biDTO.startTime}
AND create_time < #{biDTO.endTime}
AND del_flag = 1



            AND scope_org_id IN


            AND scope_user_id IN



        #{dataId}


) AS newCustomer,
/* 转成交客户*/
(SELECT
COUNT(DISTINCT customer_id)
FROM
crm_on_contract
WHERE
create_time > #{biDTO.startTime}
AND create_time < #{biDTO.endTime}
AND del_flag = 1



            AND scope_org_id IN


            AND scope_user_id IN



        #{dataId}


) AS conCustomer,
/* 放入公海客户*/
(SELECT
COUNT(DISTINCT id)
FROM
crm_pre_customer
WHERE
update_time > #{biDTO.startTime}
AND update_time < #{biDTO.endTime}
AND del_flag = 1

    AND module_id IN

        #{moduleId}





            AND scope_org_id IN


            AND scope_user_id IN



        #{dataId}


) AS toOpenCustomer,
/* 公海池客户*/
(SELECT
COUNT(DISTINCT id)
FROM
crm_pre_customer
WHERE
update_time > #{biDTO.startTime}
AND update_time < #{biDTO.endTime}
AND del_flag = 1

    AND module_id IN

        #{moduleId}


) AS openCustomer,
/* 新增商机*/
(SELECT
COUNT(DISTINCT customer_id)
FROM
crm_on_business
WHERE
create_time > #{biDTO.startTime}
AND create_time < #{biDTO.endTime}
AND del_flag = 1



            AND scope_org_id IN


            AND scope_user_id IN



        #{dataId}


) AS newBusiness,
/* 赢单商机*/
(SELECT
COUNT(1)
FROM
crm_on_business
WHERE
create_time > #{biDTO.startTime}
AND create_time < #{biDTO.endTime}
AND data_type = 1
AND del_flag = 1



            AND scope_org_id IN


            AND scope_user_id IN



        #{dataId}


) AS winBusiness,
/* 输单商机*/
(SELECT
COUNT(1)
FROM
crm_on_business
WHERE
create_time > #{biDTO.startTime}
AND create_time < #{biDTO.endTime}
AND data_type = 2
AND del_flag = 1



            AND scope_org_id IN


            AND scope_user_id IN



        #{dataId}


) AS losBusiness,
/* 商机总金额*/
(SELECT
SUM(real_money)
FROM
crm_on_business
WHERE
create_time > #{biDTO.startTime}
AND create_time < #{biDTO.endTime}
AND data_type = 1
AND del_flag = 1



            AND scope_org_id IN


            AND scope_user_id IN



        #{dataId}


) AS businessMoney,
/* 签约合同*/
(SELECT
COUNT(1)
FROM
crm_on_contract
WHERE
create_time > #{biDTO.startTime}
AND create_time < #{biDTO.endTime}
AND data_type = 1
AND del_flag = 1



            AND scope_org_id IN


            AND scope_user_id IN



        #{dataId}


) AS newContract,
/* 即将到期*/
(SELECT
COUNT(1)
FROM
crm_on_contract
WHERE
end_time > #{biDTO.startTime}
AND end_time < #{biDTO.endTime}
AND del_flag = 1



            AND scope_org_id IN


            AND scope_user_id IN



        #{dataId}


) AS dueContract,
/* 已到期*/
(SELECT
COUNT(1)
FROM
crm_on_contract
WHERE
end_time > NOW()
AND del_flag = 1



            AND scope_org_id IN


            AND scope_user_id IN



        #{dataId}


) AS expireContract,
/* 合同金额*/
(SELECT
SUM(real_money)
FROM
crm_on_contract
WHERE
create_time > #{biDTO.startTime}
AND create_time < #{biDTO.endTime}
AND del_flag = 1



            AND scope_org_id IN


            AND scope_user_id IN



        #{dataId}


) AS contractMoney,
/* 跟进客户*/
(SELECT
COUNT(DISTINCT fr.rel_data_id)
FROM
crm_on_follow_rel fr
LEFT JOIN crm_pre_customer c ON fr.rel_module_id = c.module_id AND fr.rel_data_id = c.id
WHERE
fr.create_time > #{biDTO.startTime}
AND fr.create_time < #{biDTO.endTime}
AND del_flag = 1



            AND c.scope_org_id IN


            AND c.scope_user_id IN



        #{dataId}


) AS followCustomer,
/* 新增未跟进*/
(SELECT
COUNT(1)
FROM
(
    SELECT
    c.id,
    MAX(fr.create_time) last_time
    FROM
    crm_pre_customer c
    LEFT JOIN crm_on_follow_rel fr ON fr.rel_module_id = c.module_id AND fr.rel_data_id = c.id
    WHERE
    c.create_time > #{biDTO.startTime}
    AND c.create_time < #{biDTO.endTime}
    AND c.del_flag = 1



                AND c.scope_org_id IN


                AND c.scope_user_id IN



            #{dataId}


    GROUP BY c.id
    ) AS un
    WHERE last_time IS NULL
) AS unFollowCustomer,
/* 回款*/
(SELECT
SUM(real_money)
FROM
crm_on_payment
WHERE
create_time > #{biDTO.startTime}
AND create_time < #{biDTO.endTime}
AND data_type = 102
AND del_flag = 1



            AND scope_org_id IN


            AND scope_user_id IN



        #{dataId}


) AS rePayment,
/* 预计回款*/
(SELECT
SUM(real_money)
FROM
crm_on_payment
WHERE
create_time > #{biDTO.startTime}
AND create_time < #{biDTO.endTime}
AND data_type = 101
AND del_flag = 1



            AND scope_org_id IN


            AND scope_user_id IN



        #{dataId}


) AS planPayment
